import {FRONTIER_BESTIARY} from './repertoire.js?v=5.38';
import {CREW,defaultHero} from './mako.js?v=5.16.0';
import {APPROACHES,setApproach} from './battle-approaches.js';
const copy=v=>JSON.parse(JSON.stringify(v));
export const FIELD_ORIGINS=[
 ['Delivery ridge','Sable’s last delivery crosses a wet ridge. Clay-fed creatures have chewed through the carrier cable.','storm',0],
 ['Reedbank rescue','Before the prison infirmary, Iona carried remedies through a flooded reedbank. Something is following the medicine scent.','mangrove',1],
 ['Kiln service road','Rook tests a regulator outside the foundry. The heat wakes the creatures nesting in its discarded casing.','caldera',2],
 ['Freight embankment','Brass follows a broken rail signal beyond the carriage yard. Scavengers are carrying its glass away.','crystal',3],
 ['River survey','Riven takes a river measure before the sluices open. The waterline hides more than a broken gauge.','coral',4],
 ['Windward orchard','Mira follows a stolen seed bag into a wind-cut grove. The thieves are smaller, stranger and hungrier than expected.','spore',5],
 ['Night signal','Veyr answers a signal beyond the inhabited roads. A creature is repeating the missing beat.','aurora',6]
].map(([name,text,biome,hero])=>({id:'field-'+hero,location:4700+hero,name,text,biome,hero}));
export function expandFieldOrigins(data){for(const o of FIELD_ORIGINS){if(data.scenes.some(s=>s.location===o.location))continue;const template=data.scenes.find(s=>s.biome?.id===o.biome)||data.scenes.find(s=>s.biome);if(!template)continue;const s=copy(template);Object.assign(s,{location:o.location,key:'origin_'+o.biome,chapter:1,title:o.name,fieldOrigin:o.hero,entry_text:null,entry_pages:null,doors:[],objects:[{type:'patrol',enemies:[['scout',[12,21]],['predator',[14,21]]],frontierSpecies:([[20,21],[8,9],[4,5],[18,19],[6,7],[16,17],[14,15]][o.hero]).map(i=>FRONTIER_BESTIARY[i].id),xy:[12,21],label:'Trail creatures · try your supplies',originHero:o.hero},{type:'origin-exit',xy:[6,22],label:'Change approach or leave the trail'}],arrive:[9,22]});data.scenes.push(s);}return data;}
export function originLedger(s){return s.fieldOrigins??={version:1,completed:[],roles:{}};}
export function approachChoices(w,id,after){w.choose((w.state.fieldOrigins?.active?'':FIELD_ORIGINS[id].text+'\n')+CREW[id].name+' · Choose an approach to try. Every character can use every approach; change it between battles.',APPROACHES.map(a=>[a.name+' — '+a.text,()=>{setApproach(w.state,id,a.id);originLedger(w.state).roles[id]=a.id;after?.(a);} ]));}
export function originMenu(w){if(w.state.mode==='battle')return;w.choose('BEFORE THE ROADS MEET\nPlay a short field encounter from a companion’s life before joining the crew. Supplies here are a borrowed trial kit. Your story, inventory and timeline return intact.',[...FIELD_ORIGINS.map(o=>[CREW[o.hero].name+' · '+o.name+(originLedger(w.state).completed.includes(o.hero)?' · explored':''),()=>approachChoices(w,o.hero,a=>startOrigin(w,o.hero,a.id))]),['Continue the main story',()=>exitOrigin(w)]]);}
export function startOrigin(w,id,role){const o=FIELD_ORIGINS[id];if(!o||w.state.mode==='battle')return false;if(w.state.fieldOrigins?.active)exitOrigin(w,false);const s=w.state,ledger=originLedger(s);ledger.roles[id]=role;const base=copy(s);delete base.fieldOrigins.active;delete s.chronicle;const hero={...defaultHero(id),maxHp:260,hp:260,maxMp:60,mp:60,learned:0,unlockedSlots:2,battleApproach:role,loadout:[{core:APPROACHES.find(a=>a.id===role)?.core||'earth',support:'focus'},{core:'earth',support:'focus'}]};s.heroes[id]=hero;s.party=[id];s.recruited=[id];s.cores=[...new Set(hero.loadout.map(x=>x.core))];s.supports=['focus'];s.items={tonic:3,ether:2,tideFlask:2};for(const item of (APPROACHES.find(a=>a.id===role)?.items||[]))s.items[item]=3;ledger.active={hero:id,base};w.loadScene(o.location,[9,22]);w.notice(CREW[id].name+' · '+o.name+' · '+APPROACHES.find(a=>a.id===role)?.name+' · Supplies ready');return true;}
export function exitOrigin(w,enter=true){const active=w.state.fieldOrigins?.active;if(active){const ledger=copy(w.state.fieldOrigins);delete ledger.active;const base=active.base;w.state=base;w.state.fieldOrigins=ledger;for(const [id,role]of Object.entries(ledger.roles))if(w.state.heroes[id])w.state.heroes[id].battleApproach=role;w.currentBattle=null;w.state.mode='field';w.callbacks.onScene(w.scene);w.callbacks.onMusic(w.scene.song);}if(enter){if(w.scene.key==='home'&&!w.state.story?.parcel){w.state.story.homeSeen=false;w.entry(w.scene);}else w.notice('Back on your own road. Your chosen approaches are ready.');}}
export function originInteraction(w,o){if(o.type==='origin-exit'){originMenu(w);return true;}if(o.type!=='patrol'||!Number.isInteger(o.originHero))return false;w.state.mode='battle';w.currentBattle={scene:w.scene.location,object:{...o,type:'origin',enemies:[['scout',[12,21]],['predator',[14,21]]],xy:[12,21],text:'Use Supply to set up an opening, then Attack or Mako. Guard restores focus. Retreat keeps your main story intact.'},mission:w.data.campaign.missions[0]};w.callbacks.onBattle(w.currentBattle);return true;}
export function originOutcome(w,won){if(!w.state.fieldOrigins?.active)return false;w.currentBattle=null;w.state.mode='field';const id=w.state.fieldOrigins.active.hero,ledger=originLedger(w.state);if(won&&!ledger.completed.includes(id))ledger.completed.push(id);w.rest();w.choose(won?CREW[id].name+' clears the trail. Keep this approach, or try another? No class is locked.':'The trail remains open. Try another supply combination or another approach. Your main story is safe.',[['Try this encounter again',()=>{}],['Choose another approach',()=>approachChoices(w,id,a=>startOrigin(w,id,a.id))],['Follow another character',()=>originMenu(w)],['Continue the main story',()=>exitOrigin(w)]]);return true;}
export function approachMenu(w){const ids=w.state.fieldOrigins?.active?[w.state.fieldOrigins.active.hero]:w.state.recruited;w.choose('Battle approaches · shared across the crew. Supplies still cost one item and one action. These disciplines change their use; they do not replace Mako, gear or relics.',[...ids.map(id=>[CREW[id].name+' · '+(APPROACHES.find(a=>a.id===w.state.heroes[id].battleApproach)?.name||'Undecided'),()=>approachChoices(w,id,w.state.fieldOrigins?.active?a=>startOrigin(w,id,a.id):undefined)]),['Return',()=>{}]]);}
